Local Open Scope Z_scope.
Definition RAOK (br1 : option (Z * Z)) (rk n : Z) (ra : option (PrimInt63.int * PrimInt63.int)) : Prop :=
  match ra with
  | None => True
  | Some (x, y) => match br1 with
                   | Some (lo1, hi1) => Uint63.to_Z x = lo1 + rk + 2 ^ 61 /\ Uint63.to_Z y = hi1 + rk + n + 2 ^ 61
                   | None => False
                   end
  end.
